    await run(async () => { await api(`/api/teacher/subjects/${detail.id}`, { method: "POST", body: JSON.stringify({ category: { name: categoryName, parentId: categoryParent || null, weight: Number(categoryWeight) } }) }); await loadDetail(); setCategoryName(""); setCategoryParent(""); setCategoryWeight("50"); setCategoryOpen(false); }, "Category path added. Review weights, then save the structure.");
